def effective_limit(value, default=10):
    """Return effective limit.

    - None -> default
    - 0   -> 0 (disabled)
    - positive int -> that int
    - negative int -> raise ValueError
    """
    if value is None:
        return default
    if isinstance(value, int):
        if value < 0:
            raise ValueError("negative limit not allowed")
        if value == 0:
            return 0
        if value > 0:
            return value
        # value == 0 already handled
    # value might be other type? assume int/None
    # fallback default
    return default
